using UnityEngine;

public class Match : MonoBehaviour
{
    public Game game;
    public int matchesFound; // Número de matches encontrados

    void Update()
    {
        // Procesar la lógica de match-3
        foreach (Gem gem in game.gems)
        {
            CheckMatch(gem);
        }
    }

    void CheckMatch(Gem gem)
    {
        // Verificar si el gem está en una fila/horizontal y vertical que tenga al menos 2 gems con mismo color
        // (Verifica la fila/horizontal superior e inferior)
        for (int i = -1; i <= 1; i++)
        {
            if (i == 0) continue; // Saltar sobre el gem actual

            int row = gem.row + i;
            int col = gem.col;
            Gem neighborGem = null;
            for (int j = 1; j <= 3; j++)
            {
                neighborGem = game.gems.Find(g => g.row == row && g.col == col + j * i);
                if (neighborGem != null && neighborGem.colorIndex == gem.colorIndex)
                {
                    // Match encontrado! Actualizar el score y movesLeft
                    game.score += 10;
                    game.movesLeft--;
                    matchesFound++;
                    break;
                }
            }
        }
    }
}
